script = '''
const toast = document.querySelector('.toast'); let timer;
function notify(t){toast.textContent=t;toast.hidden=false;clearTimeout(timer);timer=setTimeout(()=>toast.hidden=true,3500)}
document.querySelectorAll('.save').forEach(b=>b.onclick=()=>{const saved=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',saved);notify(saved?'معاينة: تمت إضافة العقار للمحفوظة':'معاينة: تمت إزالة العقار من المحفوظة')});
document.querySelectorAll('.chips button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chips button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.querySelector('.homephone .secondary').hidden=b.textContent==='شقة';document.querySelector('.homephone .property').hidden=b.textContent==='استوديو'||b.textContent==='فيلا';notify('فلتر توضيحي: '+b.textContent)});
document.querySelector('.search').onclick=()=>notify('البحث: مقترح بصري، الربط بالبحث الحالي عند التنفيذ');
document.querySelector('#book').onclick=()=>notify('معاينة: هنا تفتح خطوات حجز المعاينة الموجودة في التطبيق');
document.querySelector('#contact').onclick=()=>notify('معاينة: هنا تفتح المحادثة مع المالك');
let filter='all';
function update(){document.querySelectorAll('.request').forEach(r=>r.hidden=filter!=='all'&&r.dataset.state!==filter);document.querySelector('#pending-count').textContent=document.querySelectorAll('[data-state=pending]').length;document.querySelector('#confirmed-count').textContent=document.querySelectorAll('[data-state=confirmed]').length}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));update()});
document.querySelectorAll('.accept,.reject').forEach(b=>b.onclick=()=>{const r=b.closest('.request');const accept=b.classList.contains('accept');if(!confirm('معاينة فقط: '+(accept?'تأكيد قبول المعاينة؟':'تأكيد رفض الطلب؟')))return;r.dataset.state=accept?'confirmed':'rejected';r.querySelector('.state').textContent=accept?'مؤكدة':'مرفوضة';r.querySelector('.state').classList.remove('pending');r.querySelector('.requestactions').innerHTML='<div class="confirmed">'+(accept?'تم تأكيد موعد المعاينة':'تم رفض الطلب')+'</div>';update();notify('تم تحديث الطلب التوضيحي؛ لا يتم إرسال بيانات')});
'''
